package com.acme.core.infrastructure.persistence;

import com.acme.core.application.customerlite.CustomerLitePort;
import com.acme.core.application.customerlite.CustomerLiteService;
import com.acme.core.application.organization.DepartmentPort;
import com.acme.core.application.dictionary.DictionaryPort;
import com.acme.core.infrastructure.persistence.mapper.CustomerLiteMapper;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * CustomerLite bean wiring (generated by engineering-platform Generic Module Generator).
 */
@Configuration
public class CustomerLiteBeansConfig {

    @Bean
    public CustomerLitePort customerLitePort(CustomerLiteMapper mapper, DepartmentPort departmentPort) {
        return new MybatisCustomerLiteRepository(mapper, departmentPort);
    }

    @Bean
    public CustomerLiteService customerLiteService(CustomerLitePort port, DictionaryPort dictionaryPort) {
        return new CustomerLiteService(port, dictionaryPort);
    }
}
